// Verus program: find the first even index and the first odd index.
//
// Spec requirements:
// - lst.len() >= 2
// - exists an even element, and exists an odd element
// - return (i, j) where
//   * i is the smallest index with lst[i] even (all before are odd)
//   * j is the smallest index with lst[j] odd  (all before are even)

use vstd::prelude::*;

verus! {

spec fn is_even(x: i32) -> bool {
    x % 2 == 0
}

spec fn is_odd(x: i32) -> bool {
    x % 2 != 0
}

fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize)
    requires
        lst.len() >= 2,
        exists|e: int| 0 <= e < lst.len() && is_even(lst[e]),
        exists|o: int| 0 <= o < lst.len() && is_odd(lst[o]),
    ensures
        ({
            let (i, j) = result;
            i < lst.len()
                && j < lst.len()
                && is_even(lst[i as int])
                && (forall|k: int| 0 <= k < i ==> is_odd(lst[k]))
                && is_odd(lst[j as int])
                && (forall|k: int| 0 <= k < j ==> is_even(lst[k]))
        })
{
    let n = lst.len();

    // Find i = first index where lst[i] is even
    let mut i: usize = 0;
    while i < n && (lst[i] % 2 != 0)
        invariant
            i <= n,
            n == lst.len(),
            forall|k: int| 0 <= k < i ==> is_odd(lst[k]),
        decreases n - i
    {
        i += 1;
    }
    // By the precondition "exists even", the loop cannot finish with i == n.
    assert(i < n);
    assert(is_even(lst[i])); // follows from loop condition being false

    // Find j = first index where lst[j] is odd
    let mut j: usize = 0;
    while j < n && (lst[j] % 2 == 0)
        invariant
            j <= n,
            n == lst.len(),
            forall|k: int| 0 <= k < j ==> is_even(lst[k]),
        decreases n - j
    {
        j += 1;
    }
    // By the precondition "exists odd", the loop cannot finish with j == n.
    assert(j < n);
    assert(is_odd(lst[j])); // follows from loop condition being false

    (i, j)
}

} // verus!